<?php
declare(strict_types=1); namespace App\Http\Controllers\Classrooms; use App\Http\Controllers\Controller; use App\Http\Requests\Classrooms\{LegacyMappingPreviewRequest,LegacyMappingConfirmRequest}; use App\Models\{AcademicYear,Classroom}; use App\Services\Classrooms\{ClassroomLegacyMappingService,ClassroomMembershipService}; use Illuminate\Http\RedirectResponse; use Illuminate\View\View;
class ClassroomLegacyMappingController extends Controller {public function index(ClassroomLegacyMappingService $s):View{request()->user()->can('classrooms.map-legacy')?:abort(403);$years=AcademicYear::latest('starts_at')->get();$year=(int)(request('academic_year')?:AcademicYear::where('is_active',true)->value('id'));return view('classrooms.legacy',['years'=>$years,'year'=>$year,'labels'=>$year?$s->labels($year):collect(),'rooms'=>Classroom::where('academic_year_id',$year)->with('gradeLevel')->get()]);}public function preview(LegacyMappingPreviewRequest $r,ClassroomLegacyMappingService $s):View{$room=Classroom::findOrFail($r->integer('classroom_id'));return view('classrooms.legacy-preview',['preview'=>$s->preview($r->integer('academic_year_id'),$r->string('legacy_label')->toString(),$room)]);}public function confirm(LegacyMappingConfirmRequest $r,ClassroomLegacyMappingService $s,ClassroomMembershipService $m):RedirectResponse{$room=Classroom::findOrFail($r->integer('classroom_id'));$result=$s->map($r->user(),$r->integer('academic_year_id'),$r->string('legacy_label')->toString(),$room,$m);return redirect()->route('classrooms.legacy.index',['academic_year'=>$room->academic_year_id])->with('success',"Data kelas lama berhasil dipetakan: {$result['added']} siswa.");}}
